"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant2 from "./components/empty-states/variants/03-inbox";
const variants = {"inbox": Variant2};
export interface ArtemisEmptyStatesProps { className?: string; variant?: "inbox"; }
export function ArtemisEmptyStates({ className, variant = "inbox" }: ArtemisEmptyStatesProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { useEffect, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
export default function EmptyStatesInbox() {
    const reduce = useReducedMotion();
    const [stage, setStage] = useState(0);
    useEffect(() => {
        if (reduce) {
            setStage(4);
            return;
        }
        const timers = [80, 220, 380, 560].map((delay, index) => window.setTimeout(() => setStage(index + 1), delay));
        return () => timers.forEach((timer) => window.clearTimeout(timer));
    }, [reduce]);
    const spring = reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL;
    return (<>
      <section className="art:mx-auto art:flex art:w-full art:max-w-[520px] art:flex-col art:items-center art:justify-center art:text-center art:text-foreground">
        <motion.div aria-hidden="true" className="art:relative art:mb-6 art:h-[165px] art:w-[260px]" initial={{ opacity: 0, y: 12 }} animate={stage >= 1 ? { opacity: 1, y: 0 } : undefined} transition={spring}>
          <svg viewBox="0 0 260 165" className="art:absolute art:inset-0 art:size-full art:overflow-visible" role="presentation">
            <motion.path initial={{ opacity: 0, scaleY: 0.55 }} animate={stage >= 2 ? { opacity: 1, scaleY: 1 } : undefined} transition={spring} d="M18 67 130 18l112 49-112 66Z" fill="var(--artemis-muted)" stroke="var(--artemis-border)" strokeWidth="1.4" opacity="1" style={{ transformOrigin: "50% 50%", transformBox: "fill-box" }}/>
            <motion.g initial={{ opacity: 0, y: 34 }} animate={stage >= 3 ? { opacity: 1, y: -10 } : undefined} transition={spring} style={{ transformOrigin: "50% 50%", transformBox: "fill-box" }}>
              <rect x="54" y="45" width="152" height="92" rx="9" fill="var(--artemis-background)" stroke="var(--artemis-foreground)" strokeWidth="1.4"/>
              <path d="M75 72h77M75 88h108M75 104h64" stroke="var(--artemis-foreground)" strokeLinecap="round" strokeOpacity="0.48" strokeWidth="1.6"/>
              <motion.circle initial={{ opacity: 0, scale: 0.6 }} animate={stage >= 4 ? { opacity: 1, scale: 1 } : undefined} transition={spring} cx="181" cy="68" r="13" fill="var(--artemis-primary)" opacity="1" style={{ transformOrigin: "50% 50%", transformBox: "fill-box" }}/>
              <motion.path initial={{ opacity: 0, pathLength: 0 }} animate={stage >= 4 ? { opacity: 1, pathLength: 1 } : undefined} transition={reduce ? { duration: 0 } : { duration: 0.25, ease: ARTEMIS_EASE_OUT }} d="m175 68 4 4 8-9" fill="none" stroke="var(--artemis-primary-foreground)" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2"/>
            </motion.g>
            <motion.path initial={{ opacity: 0, y: 8 }} animate={stage >= 1 ? { opacity: 1, y: 0 } : undefined} transition={spring} d="M18 67 130 132 242 67v82H18Z" fill="var(--artemis-muted)" stroke="var(--artemis-border)" strokeLinejoin="round" strokeWidth="1.4" opacity="1" style={{ transformOrigin: "50% 50%", transformBox: "fill-box" }}/>
            <path d="m18 149 82-58M242 149l-82-58" fill="none" stroke="var(--artemis-border)" strokeWidth="1.4"/>
          </svg>
        </motion.div>
        <h2 className="art:text-balance art:tracking-[-0.03em] art:text-4xl art:font-medium">
          {"Inbox zero"}
        </h2>
        <p className="art:mt-2 art:max-w-xs art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
          {"You are caught up. New conversations will appear here."}
        </p>
        <ArtemisButton variant="secondary" size="sm" className="art:mt-4 art:h-9">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-pen-line art:size-3.5" aria-hidden="true">
            <path d="M13 21h8"/>
            <path d="M21.174 6.812a1 1 0 0 0-3.986-3.987L3.842 16.174a2 2 0 0 0-.5.83l-1.321 4.352a.5.5 0 0 0 .623.622l4.353-1.32a2 2 0 0 0 .83-.497z"/>
          </svg>
          {"Compose"}
        </ArtemisButton>
      </section>
    </>);
}
